def bootstrap_mean(histogram, n, rng):
    if len(histogram) == 1:
        return histogram[0][0]
    counts = multinomial(n, [c/n for _, c in histogram], rng)
    return sum(x*c for (x, _), c in zip(histogram, counts))/n

